<?php $this->layout('default'); use Moves\Services\CmsSettings as S; use Moves\Services\ExternalNotifications as X; use Moves\Services\Helpdesk as H; use Moves\Support\CmsView as V; ?>
<div class="cms-grid-2"><div><form class="cms-card" method="post" action="/acao/notifications-save"><h2>Canais</h2><?= V::csrf() ?><?php foreach (S::NOTIFY_FIELDS as $key => $label): ?><?= V::field($label, $key, S::get($key, '0'), ['type' => 'checkbox']) ?><?php endforeach; ?><button class="cms-btn-primary">Salvar</button></form>
<form class="cms-card" method="post" action="/acao/sla-save"><h2>Metas de atendimento (minutos)</h2><p><small>Vazio significa sem meta. O cliente não vê estes prazos.</small></p><?= V::csrf() ?><div class="cms-table-wrap"><table><thead><tr><th>Prioridade</th><th>Primeira resposta</th><th>Resolução</th></tr></thead><tbody><?php foreach (H::slaTargets() as $s): $p = $s['priority']; ?><tr><td><?= V::e(V::PRIORITIES[$p]) ?></td><td><input type="number" min="1" aria-label="Primeira resposta <?= V::e(V::PRIORITIES[$p]) ?>" name="first[<?= V::e($p) ?>]" value="<?= V::e($s['first_response_minutes']) ?>"></td><td><input type="number" min="1" aria-label="Resolução <?= V::e(V::PRIORITIES[$p]) ?>" name="resolution[<?= V::e($p) ?>]" value="<?= V::e($s['resolution_minutes']) ?>"></td></tr><?php endforeach; ?></tbody></table></div><button class="cms-btn-primary">Salvar metas</button></form>
<div class="cms-card"><h2>Entregas externas recentes</h2><?php $rows = X::recent(); if ($rows === []): ?><?= V::empty('Nenhum aviso externo registrado.') ?><?php else: ?><div class="cms-table-wrap"><table><thead><tr><th>Canal</th><th>Evento</th><th>Situação</th><th class="num">Tentativas</th><th>Erro</th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td><?= V::e($r['channel']) ?></td><td><?= V::e($r['dedupe_key']) ?></td><td><?= V::badge($r['status'] === 'sent' ? 'active' : ($r['status'] === 'failed' ? 'failed' : 'pending'), $r['status']) ?></td><td class="num"><?= (int) $r['attempts'] ?></td><td><?= V::e($r['last_error'] ?? '') ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div>
<aside class="cms-card"><h2>Situação dos canais</h2><dl class="cms-dl"><dt>Notificações internas</dt><dd><?= V::badge('active', 'Ativas') ?></dd><dt>Telegram</dt><dd><?= X::telegramConfigured() ? V::badge('active', 'Credenciais presentes') : V::badge('pending', 'Aguardando credenciais') ?></dd><dt>E-mail</dt><dd><?= X::emailConfigured() ? V::badge('active', 'SMTP configurado') : V::badge('pending', 'SMTP incompleto') ?></dd><dt>WhatsApp</dt><dd><?= V::badge('neutral', 'Não integrado') ?></dd></dl><p><small>Credenciais ficam no arquivo .env e nunca são editadas aqui. Os avisos são enviados por scripts/process-notifications.php.</small></p></aside></div>
